package main

import (
	"fmt"
	"math"
)

func main() {
	var n, m int
	fmt.Scan(&n, &m)

	total := n * m
	if total == 1 {
		fmt.Println(0)
		return
	}

	// We need to find the maximum number of cells that can be empty.
	// This is equivalent to finding the minimum number of cells that must have at least one spider.
	// Each spider starts at a cell and moves to an adjacent cell (or stays).
	// We want to maximize the number of cells with no spiders.
	// This is a maximum matching problem on a bipartite graph.
	// Left side: initial positions (n*m nodes)
	// Right side: final positions (n*m nodes)
	// Edge from initial i to final j if spider at i can move to j (including staying).
	// We want to find the maximum matching. The number of matched edges is the minimum number of cells that have spiders.
	// So the answer is total - maxMatching.

	// Build bipartite graph
	// Node indices: 0 to total-1 for both sides
	// For each initial cell (r, c), it can go to (r, c), (r-1, c), (r+1, c), (r, c-1), (r, c+1) if valid.

	adj := make([][]int, total)
	for r := 0; r < n; r++ {
		for c := 0; c < m; c++ {
			u := r*m + c
			// stay
			adj[u] = append(adj[u], u)
			// up
			if r > 0 {
				adj[u] = append(adj[u], (r-1)*m+c)
			}
			// down
			if r < n-1 {
				adj[u] = append(adj[u], (r+1)*m+c)
			}
			// left
			if c > 0 {
				adj[u] = append(adj[u], r*m+c-1)
			}
			// right
			if c < m-1 {
				adj[u] = append(adj[u], r*m+c+1)
			}
		}
	}

	// Hopcroft-Karp or simple DFS-based bipartite matching
	// Since total <= 40, simple DFS is fine.
	matchR := make([]int, total) // matchR[v] = u matched to v, or -1
	for i := range matchR {
		matchR[i] = -1
	}

	var dfs func(u int, visited []bool) bool
	dfs = func(u int, visited []bool) bool {
		for _, v := range adj[u] {
			if visited[v] {
				continue
			}
			visited[v] = true
			if matchR[v] == -1 || dfs(matchR[v], visited) {
				matchR[v] = u
				return true
			}
		}
		return false
	}

	maxMatching := 0
	for u := 0; u < total; u++ {
		visited := make([]bool, total)
		if dfs(u, visited) {
			maxMatching++
		}
	}

	fmt.Println(total - maxMatching)
}
