	// Left nodes: 0 to total-1 (each cell)
	// Right nodes: 0 to total-1 (each cell)

	// For each cell (r, c), the spider can move to:
	// (r, c) - stay
	// (r-1, c) - up
	// (r+1, c) - down
	// (r, c-1) - left
	// (r, c+1) - right
	// if within bounds

	// adjacency list for left nodes
	adj := make([][]int, total)
	for r := 0; r < n; r++ {
		for c := 0; c < m; c++ {
			leftNode := r*m + c
			// stay
			adj[leftNode] = append(adj[leftNode], leftNode)
			// up
			if r > 0 {
				adj[leftNode] = append(adj[leftNode], (r-1)*m+c)
			}
			// down
			if r < n-1 {
				adj[leftNode] = append(adj[leftNode], (r+1)*m+c)
			}
			// left
			if c > 0 {
				adj[leftNode] = append(adj[leftNode], r*m+c-1)
			}
			// right
			if c < m-1 {
				adj[leftNode] = append(adj[leftNode], r*m+c+1)
			}
		}
	}

	// Hopcroft-Karp algorithm for maximum bipartite matching
	// pairU[i] = which right node is matched to left node i, or -1
	// pairV[j] = which left node is matched to right node j, or -1
	pairU := make([]int, total)
	pairV := make([]int, total)
	for i := range pairU {
		pairU[i] = -1
		pairV[i] = -1
	}

	// dist[i] = distance for BFS
	dist := make([]int, total)

	// BFS to find augmenting paths
	bfs := func() bool {
		queue := []int{}
		for i := 0; i < total; i++ {
			if pairU[i] == -1 {
				dist[i] = 0
				queue = append(queue, i)
			} else {
				dist[i] = math.MaxInt32
			}
		}

		found := false
		for len(queue) > 0 {
			u := queue[0]
			queue = queue[1:]
			for _, v := range adj[u] {
				nextU := pairV[v]
				if nextU != -1 && dist[nextU] == math.MaxInt32 {
					dist[nextU] = dist[u] + 1
					queue = append(queue, nextU)
				}
				if nextU == -1 {
					found = true
				}
			}
		}
		return found
	}

	// DFS to find augmenting path
	var dfs func(u int) bool
	dfs = func(u int) bool {
		for _, v := range adj[u] {
			nextU := pairV[v]
			if nextU == -1 || (dist[nextU] == dist[u]+1 && dfs(nextU)) {
				pairU[u] = v
				pairV[v] = u
				return true
			}
		}
		dist[u] = math.MaxInt32
		return false
	}

	matching := 0
	for bfs() {
		for i := 0; i < total; i++ {
			if pairU[i] == -1 {
				if dfs(i) {
					matching++
				}
			}
		}
	}

	// The maximum number of empty cells is total - matching
	fmt.Println(total - matching)
}
