	// Right side: cells (possible destinations)
	// Edge from spider at (i,j) to cell (i',j') if the spider can move from (i,j) to (i',j') in one step.
	// We want to find the minimum number of cells that can cover all spiders, i.e., minimum vertex cover on the bipartite graph.
	// By Konig's theorem, minimum vertex cover = maximum matching.
	// So the minimum number of occupied cells = maximum matching size.
	// Maximum empty cells = total - maximum matching.

	// Build bipartite graph
	// Left nodes: 0 to total-1 (spider at cell idx)
	// Right nodes: 0 to total-1 (cell idx)

	// adjacency list for left nodes
	adj := make([][]int, total)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			idx := i*m + j
			// stay
			adj[idx] = append(adj[idx], idx)
			// up
			if i > 0 {
				adj[idx] = append(adj[idx], (i-1)*m+j)
			}
			// down
			if i < n-1 {
				adj[idx] = append(adj[idx], (i+1)*m+j)
			}
			// left
			if j > 0 {
				adj[idx] = append(adj[idx], i*m+j-1)
			}
			// right
			if j < m-1 {
				adj[idx] = append(adj[idx], i*m+j+1)
			}
		}
	}

	// Hopcroft-Karp algorithm for maximum bipartite matching
	// pairU[u] = matched right node for left node u, or -1
	// pairV[v] = matched left node for right node v, or -1
	pairU := make([]int, total)
	pairV := make([]int, total)
	for i := range pairU {
		pairU[i] = -1
	}
	for i := range pairV {
		pairV[i] = -1
	}

	// dist for BFS
	dist := make([]int, total)

	bfs := func() bool {
		queue := make([]int, 0)
		for u := 0; u < total; u++ {
			if pairU[u] == -1 {
				dist[u] = 0
				queue = append(queue, u)
			} else {
				dist[u] = math.MaxInt32
			}
		}
		found := false
		for len(queue) > 0 {
			u := queue[0]
			queue = queue[1:]
			for _, v := range adj[u] {
				nextU := pairV[v]
				if nextU == -1 {
					found = true
				} else if dist[nextU] == math.MaxInt32 {
					dist[nextU] = dist[u] + 1
					queue = append(queue, nextU)
				}
			}
		}
		return found
	}

	dfs := func(u int) bool {
		for _, v := range adj[u] {
			nextU := pairV[v]
			if nextU == -1 || (dist[nextU] == dist[u]+1 && dfs(nextU)) {
				pairU[u] = v
				pairV[v] = u
				return true
			}
		}
		dist[u] = math.MaxInt32
		return false
	}

	matching := 0
	for bfs() {
		for u := 0; u < total; u++ {
			if pairU[u] == -1 {
				if dfs(u) {
					matching++
				}
			}
		}
	}

	emptyCells := total - matching
	fmt.Println(emptyCells)
}
