	// dp[n-1][a][b] where a = mask for row n-2, b = mask for row n-1
	// We need to check that all cells in row n-1 are dominated.
	// There's no row n, so c = 0.
	minDom := INF
	for a := 0; a < size; a++ {
		for b := 0; b < size; b++ {
			if dp[n-1][a][b] == INF {
				continue
			}
			// Check if row n-1 is dominated with a (row n-2), b (row n-1), c=0 (no row n)
			if isRowDominated(n-1, a, b, 0, m) {
				if dp[n-1][a][b] < minDom {
					minDom = dp[n-1][a][b]
				}
			}
		}
	}

