	if n == 1 {
		// Only one row. dp[0][0][b] for all b.
		// We need to check that row 0 is dominated with a=0, b=b, c=0.
		for b := 0; b < size; b++ {
			if dp[0][0][b] == INF {
				continue
			}
			if isRowDominated(0, 0, b, 0, m) {
				if dp[0][0][b] < minDom {
					minDom = dp[0][0][b]
				}
			}
		}
	}

	answer := total - minDom
	fmt.Println(answer)
}

func popcount(x int) int {
	c := 0
	for x > 0 {
		c += x & 1
		x >>= 1
	}
	return c
}

// isRowDominated checks if all cells in row i are dominated
// given the masks for row i-1 (a), row i (b), and row i+1 (c)
func isRowDominated(i int, a, b, c, m int) bool {
	for col := 0; col < m; col++ {
		dominated := false
		// Cell (i, col) is in S?
		if b&(1<<col) != 0 {
			dominated = true
		}
		// Left neighbor in same row?
		if !dominated && col > 0 && b&(1<<(col-1)) != 0 {
			dominated = true
		}
		// Right neighbor in same row?
		if !dominated && col < m-1 && b&(1<<(col+1)) != 0 {
			dominated = true
		}
		// Up neighbor (row i-1)?
		if !dominated && a&(1<<col) != 0 {
			dominated = true
		}
		// Down neighbor (row i+1)?
		if !dominated && c&(1<<col) != 0 {
			dominated = true
		}
		if !dominated {
			return false
		}
	}
	return true
}
